const config=window.FULLTANK_CONFIG||{};
const slider=document.querySelector('#litros');
function calculate(){if(!slider)return;const liters=Number(slider.value);document.querySelector('#litrosValor').textContent=liters;document.querySelector('#economiaValor').textContent=(liters*.1).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});document.querySelector('#formula').textContent=`${liters} L × R$ 0,10 por litro`;}
if(slider){slider.addEventListener('input',calculate);calculate();}
const modal=document.querySelector('#notice');
function notice(title,text){document.querySelector('#noticeTitle').textContent=title;document.querySelector('#noticeText').textContent=text;modal.showModal();}
document.querySelectorAll('.close,.close-action').forEach(b=>b.addEventListener('click',()=>modal.close()));
function safeUrl(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:null;}catch{return null;}}
document.querySelectorAll('[data-store]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.store==='ios'?'iosUrl':'androidUrl';const url=safeUrl(config[key]);if(url){window.open(url,'_blank','noopener,noreferrer');}else notice('Download do Fulltank+','Os links oficiais das lojas estão sendo preparados para esta página. Nenhum download foi iniciado.');}));
const form=document.querySelector('#leadForm');
if(form)form.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const phone=data.telefone.replace(/\D/g,'');if(phone.length<10||phone.length>13){document.querySelector('#formStatus').textContent='Confira seu WhatsApp com DDD.';return;}const message=`Olá! Quero conhecer o Fulltank+ para meu posto.\nNome: ${data.nome}\nWhatsApp: ${data.telefone}\nPosto/rede: ${data.posto}\nCidade: ${data.cidade}\nUnidades: ${data.unidades}`;const destination=String(config.salesWhatsapp||'').replace(/\D/g,'');if(destination.length>=12&&destination.length<=15){window.open(`https://wa.me/${destination}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');document.querySelector('#formStatus').textContent='Continue no WhatsApp para enviar sua solicitação. O formulário não envia dados automaticamente.';}else{notice('Contato comercial em preparação','O canal comercial ainda não foi configurado. Seus dados não foram enviados nem armazenados.');document.querySelector('#formStatus').textContent='Nenhum dado enviado. Canal comercial pendente de configuração.';}});
document.querySelectorAll('[data-screen]').forEach(button=>button.addEventListener('click',()=>{const image=document.querySelector('#appScreen');const names={'app.webp':'Tela real de abastecimento','beneficios.webp':'Tela real de benefícios e identificação de bomba','postos.webp':'Lista real de postos participantes'};image.src=`assets/${button.dataset.screen}`;image.alt=names[button.dataset.screen];image.classList.remove('screen-changing');requestAnimationFrame(()=>image.classList.add('screen-changing'));document.querySelectorAll('[data-screen]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
document.querySelector('#year').textContent=new Date().getFullYear();
